\begin{lemma}[the conormal map is injective]\label{lem:conormal-injective}
\Verified\ In the setting above, $N^*_{S/\mathcal X}\simeq\mathcal O_S$,
and its generator maps to $dg|_S$.  Multiplication by $dg|_S$ is injective,
so
\[
0\longrightarrow\mathcal O_S
\xrightarrow{\,h\mapsto h\,dg\,}
\Omega^1_{\mathcal X}|_S\longrightarrow\Omega^1_S\longrightarrow0
\tag{5.4}
\]
is exact.
\end{lemma}

\begin{lemma}[normalization--conductor exact sequence]
\label{lem:conductor-square}
\Verified\ The sequence
\[
0\longrightarrow\mathcal O_S
\xrightarrow{\alpha}
\eta_*\mathcal O_{\widetilde S}\oplus\mathcal O_D
\xrightarrow{\beta}
\eta_*\mathcal O_{\widetilde D}
\longrightarrow0,
\tag{5.5}
\]
\[
\alpha(h)=(\eta^*h,h|_D),\qquad
\beta(\widetilde h,k)=
\widetilde h|_{\widetilde D}-\eta^*k,
\]
is exact.
\end{lemma}

\begin{theorem}[nodal-cubic test family]\label{prop:nodal-counterexample}
\Refuted\ The p.~692 implication described after (5.2) is false as a formal
sheaf-theoretic statement, even for a proper family with smooth total space
and an irreducible reduced normal-crossings central fibre.
\end{theorem}

\begin{theorem}[the candidate conductor mechanism, with all hypotheses]
\label{thm:candidate-conductor}
\Verified\ Assume:
\begin{enumerate}[label=(H\arabic*)]
\item $X$ is a connected compact smooth complex threefold and
$f:X\to B$ is a nonconstant holomorphic map to a smooth compact curve;
\item $W=f^{-1}(p_0)$ is the full scheme-theoretic fibre, is reduced, and
has the normal-crossings local models (5.3);
\item the normalization $\eta:\widetilde W\to W$ is the degree-six del
Pezzo surface $\mathrm{dP}_6$;
\item $H^2(X;\mathbb Z)=0$.
\end{enumerate}
Then, for every $L\in\operatorname{Pic}(X)$,
\[
H^2(W,(T_X\otimes L)|_W)\ne0
\quad\text{and}\quad
R^2f_*(T_X\otimes L)\ne0.
\tag{5.18}
\]
\end{theorem}

\begin{lemma}[left exactness of the conormal sequence]
\label{lem:conormal}
There is a short exact sequence
\[
0\longrightarrow N^*_{S/X}\longrightarrow \Omega^1_X|_S
\xrightarrow{\rho_0}\Omega^1_S\longrightarrow0.
\tag{2.1}
\]
\end{lemma}

\begin{corollary}
\label{cor:normal-crossing-kernel}
If, in addition, $H^0(S,N^*_{S/X}\otimes A)=0$ and
$H^0(S,\widetilde\Omega^1_S\otimes A)=0$, then the section in
Proposition~\ref{prop:conductor-differential} proves that $\delta_A$ in
(2.9) is not injective.
\end{corollary}

\begin{corollary}[the intact relative hypothesis]
\label{cor:relative}
In the setting of Theorem~\ref{thm:corrected-global}, it is enough to assume
that one line bundle $L$ satisfies
\[
 R^2f_*(T_X\otimes L)=0.
 \tag{5.8}
\]
\end{corollary}

\begin{proposition}[crossing and multiple-fibre modules]
\label{prop:relative-local}
The symbols $R_2$ and $R_3$ denote copies of the same regular local ring,
with different maps from the one-dimensional base:
let $R_2=\C\{x,y,z\}$ with base coordinate $t=xy$, and let
$R_3=\C\{x,y,z\}$ with base coordinate $t=xyz$.  Then
\[
\begin{aligned}
 M_2&:=\Omega^1_{R_2/\C\{t\}}
 =\frac{R_2\,dx\oplus R_2\,dy\oplus R_2\,dz}
        {R_2\,(y\,dx+x\,dy)},\\[2pt]
 M_3&:=\Omega^1_{R_3/\C\{t\}}
 =\frac{R_3\,dx\oplus R_3\,dy\oplus R_3\,dz}
        {R_3\,(yz\,dx+xz\,dy+xy\,dz)}.
\end{aligned}
\tag{6.1}
\]
Both modules are torsion-free, but neither is locally free at the origin.
They embed in free modules by
\[
\begin{aligned}
 M_2&\hookrightarrow R_2e\oplus R_2dz,
 &dx&\longmapsto xe,&dy&\longmapsto-ye,&dz&\longmapsto dz,\\
 M_3&\hookrightarrow R_3e_1\oplus R_3e_2,
 &dx&\longmapsto xe_1,&dy&\longmapsto ye_2,&dz&\longmapsto-z(e_1+e_2),
\end{aligned}
\tag{6.2}
\]
with images
\[
 R_2dz\oplus (x,y)e,
 \qquad
 R_3xe_1+R_3ye_2+R_3z(e_1+e_2).
\tag{6.3}
\]
If $R_m=\C\{s,y_1,y_2\}$ and the base coordinate is $t=s^m$ with
$m\ge2$, then
\[
\Omega^1_{R_m/\C\{t\}}
\simeq R_m\,dy_1\oplus R_m\,dy_2
       \oplus R_m/(s^{m-1})\,ds,
\tag{6.4}
\]
and the final summand is exactly its torsion submodule.
\end{proposition}
